from pathlib import Path
import json,hashlib
R=Path.cwd();D=R/'build/movie-audition';old=json.loads((D/'pre-classic-integration-hashes.json').read_text(encoding='utf8'));records=json.loads((D/'reactions.json').read_text(encoding='utf8'))
assert len(records)==90
assert all(hashlib.sha256((D/f).read_bytes()).hexdigest()==h for f,h in old.items())
assert len({r['sha256'] for r in records})==90
assert {r['file'] for r in records}-set(old)=={'good-38.wav','good-39.wav'}
p=R/'audio-bank/README.md';s=p.read_text(encoding='utf8').replace('88 extraits préparés','90 extraits préparés').replace('44 réactions positives et 44 négatives','46 réactions positives et 44 négatives').replace('tirées de 28 œuvres : 78 extraits en français, 8 en anglais','tirées de 30 œuvres : 78 extraits en français, 10 en anglais');s=s.replace('Certaines additions sont','Deux répliques James Bond approuvées ont ensuite été intégrées : « Perfect. Cheers. » et « Well done. Congratulations. ». La sélection classique complète est approuvée ; 19 autres lignes attendent encore leur audio (voir `CLASSIC-REACTIONS.md`). Certaines additions sont');p.write_text(s,encoding='utf8')
p=R/'audio-bank/CLASSIC-REACTIONS.md';s=p.read_text(encoding='utf8');s=s.replace('21 pistes sourcées, dont 2 découpes audio locales pour audition. Elles restent séparées des 88 réactions préparées : aucune sélection ni annotation existante n’a changé.','Les 21 pistes ont été approuvées par l’utilisateur. Les 2 répliques Bond disponibles sont intégrées à la banque privée, désormais composée de 90 extraits (46 positifs et 44 négatifs). Les 19 autres sélections restent approuvées mais attendent un fichier audio exploitable. Les 88 fichiers précédents et leurs annotations sont conservés.').replace('mais attendent une écoute humaine.','et leur sélection a été approuvée par l’utilisateur.').replace(' ; fichier local',' ; intégrée à la banque');p.write_text(s,encoding='utf8')
p=R/'build/classic-audio/index.html';s=p.read_text(encoding='utf8').replace('Aucun ajout activé dans la banque du jeu.','Sélection complète approuvée. Les deux fichiers Bond sont intégrés à la banque privée ; 19 autres répliques attendent leur audio.').replace('Short cut decoded and checked with speech recognition; human listening review pending.','Selection approved by user; normalized cut integrated into the private bank.');p.write_text(s,encoding='utf8')
print('Verified 90 distinct audio files; all 88 existing hashes preserved; documentation updated.')
